SET NOCOUNT ON;SET XACT_ABORT ON;INSERT lab.Evidence SELECT 'PLANNED_GROWTH',(SELECT COUNT(*) FROM sys.dm_db_log_info(DB_ID())),size*8.0/1024,growth*8.0/1024 FROM sys.database_files WHERE type=1;IF NOT EXISTS(SELECT 1 FROM lab.Evidence WHERE Stage='PLANNED_GROWTH' AND GrowthMB=64) THROW 51006,'FAIL_RESULT_CONTRACT: Geplanter Growth-Schritt fehlt.',1;SELECT * FROM lab.Evidence ORDER BY Stage;PRINT 'SQLPERF_SUMMARY|PASS|OK';
